payload.tpl:
validations:
  - expression: object.spec.containers[0].env.exists(e, e.name=='FAIL_FAST' && e.value=='1') == false
validationActions: {{ .Values.validationActions }}

matchConditions:
  - name: {{ .Values.matchCondition }}
    expression: object.spec.containers.exists(c, c.env.exists(e, e.name=='FAIL_FAST'))
